"""Load the packaged JSON data (generated by scripts/build/generate.py; do not edit)."""

from __future__ import annotations

import json
from functools import lru_cache
from importlib import resources


@lru_cache(maxsize=None)
def load(name: str):
    text = resources.files("naija_data").joinpath("_data", f"{name}.json").read_text(encoding="utf-8")
    return json.loads(text)
